draw(((0,-.7)--(2.3,-.7)));
draw(((5.7,-.7)--(8,-.7)));
draw(((0,-.5)--(0,-.9)));
draw(((8,-.5)--(8,-.9)));
label("80 cm",(4,0),S);
draw(((-1.8,0)--(-1.8,2.5)));
draw(((-1.8,3.5)--(-1.8,6)));
